-- daily_goals: target из profiles.daily_goal_xp (или 20 default).
ON CONFLICT (user_id) DO NOTHING;

-- daily_goal_progress: текущий день для всех завершивших онбординг.
ON CONFLICT (user_id, date) DO NOTHING;

-- streak_history: последние N дней для активных юзеров (streak > 0).
ON CONFLICT (user_id, date) DO NOTHING;

-- xp_transactions: распределяем total_xp на 1-5 транзакций per user.
ON CONFLICT DO NOTHING;
